"""Deploys OptionPricingModel to Ganache and writes the address into app.py.

Run from the project folder (Ganache must be open):
    py deploy.py
"""
import json, os, re, sys
from web3 import Web3

RPC_URL = "http://127.0.0.1:7545"
HERE = os.path.dirname(os.path.abspath(__file__))
BYTECODE = ""

w3 = Web3(Web3.HTTPProvider(RPC_URL))
if not w3.is_connected():
    sys.exit("Can't reach Ganache at " + RPC_URL + ". Open Ganache (Quickstart) and try again.")

with open(os.path.join(HERE, "assets", "abi.json")) as f:
    abi = json.load(f)

deployer = w3.eth.accounts[0]
print("Deploying from", deployer, "...")
tx = w3.eth.contract(abi=abi, bytecode=BYTECODE).constructor().transact({"from": deployer})
receipt = w3.eth.wait_for_transaction_receipt(tx)
address = receipt.contractAddress
print("Contract deployed at", address, "in block", receipt.blockNumber)

app_path = os.path.join(HERE, "app.py")
with open(app_path, encoding="utf-8") as f:
    code = f.read()
code = re.sub(r'CONTRACT_ADDRESS = "[^"]*"', 'CONTRACT_ADDRESS = "' + address + '"', code, count=1)
with open(app_path, "w", encoding="utf-8") as f:
    f.write(code)
print("app.py updated. Now run:  py -m streamlit run app.py")

users = os.path.join(HERE, "users.json")
if os.path.exists(users):
    os.remove(users)
    print("Old users.json removed (it belonged to a previous chain). Sign up again in the app.")
